/**
 * Dub a finished clip with a clean Russian voice.
 *
 * Video models voice Russian badly, so we throw their audio away and put a
 * free Edge TTS voice in its place, mix a quiet music bed under it, and burn
 * the hook and subtitles in. Works on any local mp4 — one generated by Veo,
 * or one the owner made by hand in the Gemini app.
 *
 * The voice is free (msedge-tts): no credits, no quota.
 *
 * Requires ffmpeg and ffprobe in PATH.
 */
import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import os from "node:os";
import { fileURLToPath } from "node:url";

import { MsEdgeTTS, OUTPUT_FORMAT } from "msedge-tts";
import { findFont, wrapText } from "./assemble.mjs";

const ROOT = path.resolve(fileURLToPath(new URL("../..", import.meta.url)));
export const DEFAULT_MUSIC = path.join(ROOT, "scripts", "assets", "music-bed.mp3");

/** Russian voices: Dmitry (male), Svetlana (female). */
export const DEFAULT_VOICE = "ru-RU-DmitryNeural";
/** Slightly slower reads as deadpan. */
export const DEFAULT_RATE = "-6%";
export const DEFAULT_MUSIC_VOLUME = 0.22;

/** Run ffmpeg/ffprobe; resolve stdout or reject with the tail of stderr. */
function run(bin, args) {
  return new Promise((resolve, reject) => {
    const proc = spawn(bin, args, { stdio: ["ignore", "pipe", "pipe"] });
    let out = "";
    let err = "";
    proc.stdout.on("data", (d) => (out += d));
    proc.stderr.on("data", (d) => (err += d));
    proc.on("error", (e) =>
      reject(new Error(`Не удалось запустить ${bin}: ${e.message}. Установлен ли ffmpeg?`)),
    );
    proc.on("close", (code) => {
      if (code === 0) resolve(out.trim());
      else
        reject(
          new Error(`${bin} завершился с кодом ${code}:\n${err.trim().split("\n").slice(-6).join("\n")}`),
        );
    });
  });
}

/** Duration of a media file, in seconds. */
export async function duration(file) {
  const out = await run("ffprobe", [
    "-v",
    "error",
    "-show_entries",
    "format=duration",
    "-of",
    "csv=p=0",
    file,
  ]);
  return Number.parseFloat(out) || 0;
}

/** Synthesise the free Russian voice-over; returns a path to an mp3. */
/**
 * Find when the original clip actually speaks: [start, end] in seconds.
 *
 * The video model animates the mouth under ITS audio. If we drop a Russian
 * voice in at a fixed offset, the lips and the words drift apart — that is the
 * mismatch viewers notice. So we read the speech window out of the source audio
 * with silencedetect and later fit our voice into exactly that window.
 *
 * Returns null when the clip has no usable audio, so callers can fall back.
 */
/** Прогоняет ffmpeg и отдаёт stderr — там пишут volumedetect и silencedetect. */
function probe(file, filter) {
  return new Promise((resolve) => {
    const proc = spawn("ffmpeg", ["-i", file, "-af", filter, "-f", "null", "-"], {
      stdio: ["ignore", "ignore", "pipe"],
    });
    let err = "";
    proc.stderr.on("data", (d) => (err += d));
    proc.on("error", () => resolve(""));
    proc.on("close", () => resolve(err));
  });
}

export async function speechWindow(file) {
  const total = await duration(file);

  // Порог тишины считаем от самого ролика. Фиксированный не годится: в клипах
  // видеомодели под речью всегда шумит улица, и при чутком пороге «речью»
  // оказывается весь ролик целиком — голос потом растягивается и договаривает
  // в тишину (ровно эта ошибка вылезла на «Павлине»).
  const vol = await probe(file, "volumedetect");
  const mean = Number((vol.match(/mean_volume:\s*(-?[\d.]+)/) || [])[1]);
  if (!Number.isFinite(mean)) return null;
  const noise = Math.min(-18, Math.max(-35, mean + 6));

  const out = await probe(file, `silencedetect=noise=${noise.toFixed(1)}dB:d=0.25`);
  if (!out) return null;

  const ends = [...out.matchAll(/silence_end:\s*([\d.]+)/g)].map((m) => Number(m[1]));
  const starts = [...out.matchAll(/silence_start:\s*([\d.]+)/g)].map((m) => Number(m[1]));

  // Речь — от конца первой тишины до начала последней.
  const start = starts.length && starts[0] < 0.15 && ends.length ? ends[0] : 0;
  const lastSilence = starts.length ? starts[starts.length - 1] : null;
  const end = lastSilence !== null && lastSilence > start + 0.4 ? lastSilence : total;

  if (!(end > start + 0.5)) return null; // окно подозрительно короткое — не доверяем
  return { start, end, noise };
}

export async function synthVoice(text, outDir, { voice = DEFAULT_VOICE, rate = DEFAULT_RATE } = {}) {
  const tts = new MsEdgeTTS();
  await tts.setMetadata(voice, OUTPUT_FORMAT.AUDIO_24KHZ_48KBITRATE_MONO_MP3);
  const { audioFilePath } = await tts.toFile(outDir, text, rate ? { rate } : undefined);
  return audioFilePath;
}

/** Escape a path for drawtext (colons and backslashes — Windows included). */
function escDrawtextPath(p) {
  return p.replace(/\\/g, "\\\\").replace(/:/g, "\\:");
}

/**
 * Replace the clip's audio with a Russian voice-over and burn in the captions.
 *
 * @param {object} o
 * @param {string} o.input               Source mp4.
 * @param {string} o.output              Finished mp4.
 * @param {string} o.text                Spoken line (also burned as subtitles).
 * @param {string} [o.hook]              Big caption over the first seconds.
 * @param {number} [o.voiceStart=0.4]    When the voice comes in, seconds.
 * @param {string} [o.voice]
 * @param {string} [o.rate]
 * @param {string|null} [o.music]        Music file, or null to disable.
 * @param {number} [o.musicVolume]
 * @returns {Promise<{output: string, voiceStart: number, music: boolean}>}
 */
export async function dubVideo({
  input,
  output,
  text,
  hook,
  voiceStart = 0.4,
  voice = DEFAULT_VOICE,
  rate = DEFAULT_RATE,
  music = DEFAULT_MUSIC,
  musicVolume = DEFAULT_MUSIC_VOLUME,
}) {
  if (!fs.existsSync(input)) throw new Error(`Ролик не найден: ${input}`);
  if (!text) throw new Error("Нечего озвучивать: пустая реплика.");

  const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "dub-"));
  try {
    const voicePath = await synthVoice(text, scratch, { voice, rate });

    const videoDur = await duration(input);
    const voiceDur = await duration(voicePath);

    // Подгоняем голос под то, как шевелится рот в исходном ролике: начинаем
    // ровно там, где начиналась речь модели, и растягиваем/поджимаем темп под
    // ту же длительность. Пофонемного совпадения это не даёт, но пропадает то,
    // что бросается в глаза: голос звучит при закрытом рте или наоборот.
    const window = await speechWindow(input).catch(() => null);
    let start = voiceStart;
    let tempo = 1;
    if (window) {
      const target = window.end - window.start;
      // Голос НИКОГДА не замедляем: растянутая речь договаривает уже при
      // закрытом рте — это первое, что видит зритель. Только ускоряем, и то
      // не сильнее 1.5, иначе получается тараторящий робот.
      tempo = Math.min(1.5, Math.max(1, voiceDur / target));
      const итог = voiceDur / tempo;
      // Короткая реплика — начинаем вместе со зверем. Длинная — подгоняем
      // конец, чтобы голос замолчал вместе с ним, пусть и начнёт чуть раньше.
      start = итог <= target ? window.start : Math.max(0, window.end - итог);
    }
    const длина = voiceDur / tempo;
    if (start + длина > videoDur) start = Math.max(0, videoDur - длина - 0.05);
    const delayMs = Math.round(start * 1000);

    const font = findFont();
    const height = 1280;

    const vparts = [];
    if (hook && font) {
      const hookFile = path.join(scratch, "hook.txt");
      fs.writeFileSync(hookFile, wrapText(hook, 16));
      vparts.push(
        `drawtext=fontfile='${escDrawtextPath(font)}':textfile='${escDrawtextPath(hookFile)}':` +
          `fontcolor=white:fontsize=${Math.round(height * 0.045)}:box=1:boxcolor=black@0.55:` +
          `boxborderw=22:x=(w-text_w)/2:y=h*0.08:line_spacing=12:enable='lt(t,2.5)'`,
      );
    }
    if (font) {
      const subFile = path.join(scratch, "sub.txt");
      fs.writeFileSync(subFile, wrapText(text, 20));
      vparts.push(
        `drawtext=fontfile='${escDrawtextPath(font)}':textfile='${escDrawtextPath(subFile)}':` +
          `fontcolor=white:fontsize=${Math.round(height * 0.034)}:box=1:boxcolor=black@0.6:` +
          `boxborderw=16:line_spacing=8:x=(w-text_w)/2:y=h*0.72:` +
          `enable='gt(t,${Math.max(0, start - 0.15).toFixed(2)})'`,
      );
    }

    const useMusic = Boolean(music) && fs.existsSync(music);
    const voiceChain = tempo === 1
      ? `adelay=${delayMs}|${delayMs},apad`
      : `atempo=${tempo.toFixed(3)},adelay=${delayMs}|${delayMs},apad`;
    const filters = [`[1:a]${voiceChain}[voice]`];
    if (useMusic) {
      filters.push(`[2:a]volume=${musicVolume}[m]`);
      filters.push(`[voice][m]amix=inputs=2:duration=longest[a]`);
    }
    const aLabel = useMusic ? "[a]" : "[voice]";
    let vMap = "0:v";
    if (vparts.length) {
      filters.push(`[0:v]${vparts.join(",")}[v]`);
      vMap = "[v]";
    }

    fs.mkdirSync(path.dirname(output), { recursive: true });
    const args = ["-y", "-i", input, "-i", voicePath];
    if (useMusic) args.push("-stream_loop", "-1", "-i", music);
    args.push(
      "-filter_complex",
      filters.join(";"),
      "-map",
      vMap,
      "-map",
      aLabel,
      "-c:v",
      "libx264",
      "-preset",
      "veryfast",
      "-crf",
      "20",
      "-pix_fmt",
      "yuv420p",
      "-c:a",
      "aac",
      "-ar",
      "44100",
      "-ac",
      "2",
      "-b:a",
      "128k",
      "-shortest",
      output,
    );

    await run("ffmpeg", args);
    return { output, voiceStart: start, music: useMusic };
  } finally {
    fs.rmSync(scratch, { recursive: true, force: true });
  }
}
